#!/usr/bin/env python3
"""Drive the freshly-booted Win 3.11 VM to the desktop via the QEMU monitor.

Boot flow: press F8 to get the interactive DOS boot, confirm every CONFIG.SYS
line (HIMEM etc.), skip AUTOEXEC.BAT (avoids the enhanced-mode net-start hang),
copy the VGA SYSTEM.INI from the floppy over the immutable snapshot's copy so the
display driver matches the -vga std adapter, then launch Windows.
"""
import socket, time, sys

SOCK = "/tmp/qemu-monitor.sock"


def mon(cmd, recv=False):
    s = socket.socket(socket.AF_UNIX)
    s.connect(SOCK)
    time.sleep(0.04)
    s.sendall((cmd + "\n").encode())
    time.sleep(0.12)
    out = b""
    if recv:
        s.settimeout(0.5)
        try:
            while True:
                out += s.recv(65536)
        except Exception:
            pass
    s.close()
    return out.decode("latin1", "replace")


def screen_text():
    raw = mon("xp/2000hx 0xb8000", recv=True)
    vals = []
    for line in raw.splitlines():
        if ":" not in line:
            continue
        for tok in line.split(":", 1)[1].split():
            try:
                vals.append(int(tok, 16))
            except ValueError:
                pass
    ch = [w & 0xFF for w in vals]
    return ["".join(chr(c) if 32 <= c < 127 else " "
                     for c in ch[r * 80:(r + 1) * 80]).rstrip() for r in range(25)]


def last_line():
    ls = [r for r in screen_text() if r.strip()]
    return ls[-1] if ls else ""


KEYMAP = {"\\": "backslash", "/": "slash", " ": "spc", ".": "dot", ":": "shift-semicolon"}


def typ(s):
    for c in s:
        mon("sendkey " + KEYMAP.get(c, c))
        time.sleep(0.05)


def enter():
    mon("sendkey ret")
    time.sleep(0.5)


def main():
    # 1. force the interactive boot menu (F8)
    t0 = time.time()
    while time.time() - t0 < 3.6:
        mon("sendkey f8")
        time.sleep(0.12)
    time.sleep(0.4)
    # 2. confirm CONFIG.SYS lines, skip AUTOEXEC.BAT
    for _ in range(30):
        ll = last_line()
        if "[Y,N]" in ll or "[N,Y]" in ll:
            mon("sendkey n" if "AUTOEXEC" in ll.upper() else "sendkey y")
            time.sleep(0.55)
        elif ll.rstrip().endswith(">"):
            break
        else:
            time.sleep(0.6)
    print("DOS prompt:", repr(last_line()), flush=True)
    # 3. drop in the VGA SYSTEM.INI (writes go to the snapshot overlay only)
    typ("copy a:\\system.ini c:\\windows\\system.ini")
    enter()
    time.sleep(0.6)
    if "verwrite" in last_line() or "Yes" in last_line():
        typ("y")
        enter()
        time.sleep(0.6)
    # 4. start Windows
    typ("c:\\windows\\win")
    enter()
    # 5. wait for the graphical desktop, dismissing any start-up dialog
    from PIL import Image
    ok = False
    for i in range(60):
        try:
            mon("screendump /tmp/win311.ppm")
            time.sleep(0.15)
            im = Image.open("/tmp/win311.ppm").convert("RGB")
        except Exception:
            time.sleep(0.8)
            continue
        cols = im.getcolors(1 << 20) or []
        nonblack = sum(c for c, col in cols if col != (0, 0, 0))
        if im.size[0] >= 640 and nonblack > 150000 and len(cols) > 6:
            im.save("/tmp/win311_desktop.png")
            ok = True
            if i > 6:
                break
        if i in (14, 20, 26):
            mon("sendkey ret")  # dismiss any start-up dialog box
        time.sleep(0.8)
    print("DESKTOP" if ok else "NO-DESKTOP", flush=True)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())

